146: export async function getLibraryPanelInputs(dashboardJson?: {
147:   __elements?: Record<string, LibraryElementExport>;
148: }): Promise<LibraryPanelInput[]> {
149:   if (!dashboardJson || !dashboardJson.__elements) {
150:     return [];
151:   }
152: 
153:   const libraryPanelInputs: LibraryPanelInput[] = [];
154: 
155:   for (const element of Object.values(dashboardJson.__elements)) {
156:     if (element.kind !== LibraryElementKind.Panel) {
157:       continue;
158:     }
159: 
160:     const model = element.model;
161:     const { type, description } = model;
162:     const { uid, name } = element;
163:     const input: LibraryPanelInput = {
164:       model: {
165:         model,
166:         uid,
167:         name,
168:         version: 0,
169:         type,
170:         kind: LibraryElementKind.Panel,
171:         description,
172:       } as LibraryElementDTO,
173:       state: LibraryPanelInputState.New,
174:     };
175: 
176:     try {
177:       const panelInDb = await getLibraryPanel(uid, true);
178:       input.state = LibraryPanelInputState.Exists;
179:       input.model = panelInDb;
180:     } catch (e: any) {
181:       if (e.status !== 404) {
182:         throw e;
183:       }
184:     }
185: 
186:     libraryPanelInputs.push(input);
187:   }
188: 
189:   return libraryPanelInputs;
190: }
