201:     const inputs = getState().importDashboard.inputs;
202: 
203:     let inputsToPersist = [] as any[];
204:     importDashboardForm.dataSources?.forEach((dataSource: DataSourceInstanceSettings, index: number) => {
205:       const input = inputs.dataSources[index];
206:       inputsToPersist.push({
207:         name: input.name,
208:         type: input.type,
209:         pluginId: input.pluginId,
210:         value: dataSource.uid,
211:       });
212:     });
213: 
214:     importDashboardForm.constants?.forEach((constant: any, index: number) => {
215:       const input = inputs.constants[index];
216: 
217:       inputsToPersist.push({
218:         value: constant,
219:         name: input.name,
220:         type: input.type,
221:       });
222:     });
223: 
224:     const result = await getBackendSrv().post('api/dashboards/import', {
225:       // uid: if user changed it, take the new uid from importDashboardForm,
226:       // else read it from original dashboard
227:       // by default the uid input is disabled, onSubmit ignores values from disabled inputs
228:       dashboard: { ...dashboard, title: importDashboardForm.title, uid: importDashboardForm.uid || dashboard.uid },
229:       overwrite: true,
230:       inputs: inputsToPersist,
231:       folderUid: importDashboardForm.folder.uid,
232:     });
233: 
234:     const dashboardUrl = locationUtil.stripBaseFromUrl(result.importedUrl);
235:     locationService.push(dashboardUrl);
236:   };
237: }
