239: const getDataSourceOptions = (input: { pluginId: string; pluginName: string }, inputModel: any) => {
240:   const sources = getDataSourceSrv().getList({ pluginId: input.pluginId });
241: 
242:   if (sources.length === 0) {
243:     inputModel.info = 'No data sources of type ' + input.pluginName + ' found';
244:   } else if (!inputModel.info) {
245:     inputModel.info = 'Select a ' + input.pluginName + ' data source';
246:   }
247: };
248: 
249: const getDataSourceDescription = (input: { usage?: InputUsage }): string | undefined => {
250:   if (!input.usage) {
251:     return undefined;
252:   }
253: 
254:   if (input.usage.libraryPanels) {
255:     const libPanelNames = input.usage.libraryPanels.reduce(
256:       (acc: string, libPanel, index) => (index === 0 ? libPanel.name : `${acc}, ${libPanel.name}`),
257:       ''
258:     );
259:     return `List of affected library panels: ${libPanelNames}`;
260:   }
261: 
262:   return undefined;
263: };
