265: export async function moveFolders(folderUIDs: string[], toFolder: FolderInfo) {
266:   const result = {
267:     totalCount: folderUIDs.length,
268:     successCount: 0,
269:   };
270: 
271:   for (const folderUID of folderUIDs) {
272:     try {
273:       const newFolderDTO = await moveFolder(folderUID, toFolder);
274:       if (newFolderDTO !== null) {
275:         result.successCount += 1;
276:       }
277:     } catch (err) {
278:       console.error('Failed to move a folder', err);
279:     }
280:   }
281: 
282:   return result;
283: }
