285: export function moveDashboards(dashboardUids: string[], toFolder: FolderInfo) {
286:   const tasks = [];
287: 
288:   for (const uid of dashboardUids) {
289:     tasks.push(createTask(moveDashboard, true, uid, toFolder));
290:   }
291: 
292:   return executeInOrder(tasks).then((result: any) => {
293:     return {
294:       totalCount: result.length,
295:       successCount: result.filter((res: any) => res.succeeded).length,
296:       alreadyInFolderCount: result.filter((res: any) => res.alreadyInFolder).length,
297:     };
298:   });
299: }
