301: async function moveDashboard(uid: string, toFolder: FolderInfo) {
302:   const fullDash: DashboardDTO = await getBackendSrv().get(`/api/dashboards/uid/${uid}`);
303: 
304:   if (
305:     ((fullDash.meta.folderUid === undefined || fullDash.meta.folderUid === null) && toFolder.uid === '') ||
306:     fullDash.meta.folderUid === toFolder.uid
307:   ) {
308:     return { alreadyInFolder: true };
309:   }
310: 
311:   const options = {
312:     dashboard: fullDash.dashboard,
313:     folderUid: toFolder.uid,
314:     overwrite: false,
315:   };
316: 
317:   try {
318:     await saveDashboard(options);
319:     return { succeeded: true };
320:   } catch (err) {
321:     if (isFetchError(err)) {
322:       if (err.data?.status !== 'plugin-dashboard') {
323:         return { succeeded: false };
324:       }
325: 
326:       err.isHandled = true;
327:     }
328:     options.overwrite = true;
329: 
330:     try {
331:       await saveDashboard(options);
332:       return { succeeded: true };
333:     } catch (e) {
334:       return { succeeded: false };
335:     }
336:   }
337: }
338: 
339: function createTask(fn: (...args: any[]) => Promise<any>, ignoreRejections: boolean, ...args: any[]) {
340:   return async (result: any) => {
341:     try {
342:       const res = await fn(...args);
343:       return Array.prototype.concat(result, [res]);
344:     } catch (err) {
345:       if (ignoreRejections) {
346:         return result;
347:       }
348: 
349:       throw err;
350:     }
351:   };
352: }
