354: export function deleteFoldersAndDashboards(folderUids: string[], dashboardUids: string[]) {
355:   const tasks = [];
356: 
357:   for (const folderUid of folderUids) {
358:     tasks.push(createTask(deleteFolder, true, folderUid, true));
359:   }
360: 
361:   for (const dashboardUid of dashboardUids) {
362:     tasks.push(createTask(deleteDashboard, true, dashboardUid, true));
363:   }
364: 
365:   return executeInOrder(tasks);
366: }
