12: 
13: var varRegex = regexp.MustCompile(`(\$\{.+?\})`)
14: 
15: type DashboardInputMissingError struct {
16: 	VariableName string
17: }
18: 
19: func (e DashboardInputMissingError) Error() string {
20: 	return fmt.Sprintf("Dashboard input variable: %v missing from import command", e.VariableName)
21: }
22: 
23: type DashTemplateEvaluator struct {
24: 	template  *simplejson.Json
25: 	inputs    []dashboardimport.ImportDashboardInput
26: 	variables map[string]string
27: 	result    *simplejson.Json
28: }
29: 
30: func NewDashTemplateEvaluator(template *simplejson.Json, inputs []dashboardimport.ImportDashboardInput) *DashTemplateEvaluator {
31: 	return &DashTemplateEvaluator{
32: 		template: template,
33: 		inputs:   inputs,
34: 	}
35: }
36: 
37: func (e *DashTemplateEvaluator) findInput(varName string, varType string) *dashboardimport.ImportDashboardInput {
38: 	for _, input := range e.inputs {
39: 		if varType == input.Type && (input.Name == varName || input.Name == "*") {
40: 			return &input
41: 		}
42: 	}
43: 
44: 	return nil
45: }
46: 
47: func (e *DashTemplateEvaluator) Eval() (*simplejson.Json, error) {
48: 	e.result = simplejson.New()
49: 	e.variables = make(map[string]string)
50: 
51: 	// check that we have all inputs we need
52: 	for _, inputDef := range e.template.Get("__inputs").MustArray() {
53: 		inputDefJson := simplejson.NewFromAny(inputDef)
54: 		inputName := inputDefJson.Get("name").MustString()
55: 		inputType := inputDefJson.Get("type").MustString()
56: 		input := e.findInput(inputName, inputType)
57: 
58: 		// force expressions value to `__expr__`
59: 		if inputDefJson.Get("pluginId").MustString() == expr.DatasourceType {
60: 			input = &dashboardimport.ImportDashboardInput{
61: 				Value: expr.DatasourceType,
62: 			}
63: 		}
64: 
65: 		if input == nil {
66: 			return nil, &DashboardInputMissingError{VariableName: inputName}
67: 		}
68: 
69: 		e.variables["${"+inputName+"}"] = input.Value
70: 	}
71: 
72: 	return simplejson.NewFromAny(e.evalObject(e.template)), nil
73: }
74: 
75: func (e *DashTemplateEvaluator) evalValue(source *simplejson.Json) any {
76: 	sourceValue := source.Interface()
77: 
78: 	switch v := sourceValue.(type) {
79: 	case string:
80: 		interpolated := varRegex.ReplaceAllStringFunc(v, func(match string) string {
81: 			replacement, exists := e.variables[match]
82: 			if exists {
83: 				return replacement
84: 			}
85: 			return match
86: 		})
87: 		return interpolated
88: 	case bool:
89: 		return v
90: 	case json.Number:
91: 		return v
92: 	case map[string]any:
93: 		return e.evalObject(source)
94: 	case []any:
95: 		array := make([]any, 0)
96: 		for _, item := range v {
97: 			array = append(array, e.evalValue(simplejson.NewFromAny(item)))
98: 		}
99: 		return array
100: 	}
101: 
102: 	return nil
103: }
104: 
105: func (e *DashTemplateEvaluator) evalObject(source *simplejson.Json) any {
106: 	result := make(map[string]any)
107: 
108: 	for key, value := range source.MustMap() {
109: 		if key == "__inputs" {
110: 			continue
111: 		}
112: 		result[key] = e.evalValue(simplejson.NewFromAny(value))
113: 	}
114: 
115: 	return result
116: }
117: "}

