{"text":"URL: https://demo.sourcegraph.com/github.com/sg-evals/grafana--v10.2.0@6e54105447cef3c8b1025b1a3d5e76cd20213659/-/blob/public/app/features/dashboard/state/PanelModel.ts%3FL200-450
200:    * Change will cause unmount and re-init of panel
201:    */
202:   key: string;
203: 
204:   /**
205:    * The PanelModel event bus only used for internal and legacy angular support.
206:    * The EventBus passed to panels is based on the dashboard event model.
207:    */
208:   events: EventBusSrv;
209: 
210:   private queryRunner?: PanelQueryRunner;
211: 
212:   constructor(model: any) {
213:     this.events = new EventBusSrv();
214:     this.restoreModel(model);
215:     this.replaceVariables = this.replaceVariables.bind(this);
216:     this.key = uuidv4();
217:   }
218: 
219:   /** Given a persistened PanelModel restores property values */
220:   restoreModel(model: any) {
221:     // Start with clean-up
222:     for (const property in this) {
223:       if (notPersistedProperties[property] || !this.hasOwnProperty(property)) {
224:         continue;
225:       }
226: 
227:       if (model[property]) {
228:         continue;
229:       }
230: 
231:       if (typeof this[property] === 'function') {
232:         continue;
233:       }
234: 
235:       if (typeof this[property] === 'symbol') {
236:         continue;
237:       }
238: 
239:       delete this[property];
240:     }
241: 
242:     // copy properties from persisted model
243:     for (const property in model) {
244:       (this as any)[property] = model[property];
245:     }
246: 
247:     const newType = autoMigratePanelType[this.type];
248:     if (newType) {
249:       this.autoMigrateFrom = this.type;
250:       this.type = newType;
251:     }
252: 
253:     // defaults
254:     defaultsDeep(this, cloneDeep(defaults));
255: 
256:     // queries must have refId
257:     this.ensureQueryIds();
258:   }
259: 
260:   generateNewKey() {
261:     this.key = uuidv4();
262:   }
263: 
264:   ensureQueryIds() {
265:     if (this.targets && isArray(this.targets)) {
266:       for (const query of this.targets) {
267:         if (!query.refId) {
268:           query.refId = getNextRefIdChar(this.targets);
269:         }
270:       }
271:     }
272:   }
273: 
274:   getOptions() {
275:     return this.options;
276:   }
277: 
278:   get hasChanged(): boolean {
279:     return this.configRev > 0;
280:   }
281: 
282:   updateOptions(options: object) {
283:     this.options = options;
284:     this.configRev++;
285:     this.events.publish(new PanelOptionsChangedEvent());
286:     this.render();
287:   }
288: 
289:   updateFieldConfig(config: FieldConfigSource) {
290:     this.fieldConfig = config;
291:     this.configRev++;
292:     this.events.publish(new PanelOptionsChangedEvent());
293: 
294:     this.resendLastResult();
295:     this.render();
296:   }
297: 
298:   getSaveModel() {
299:     const model: any = {};
300: 
301:     for (const property in this) {
302:       if (notPersistedProperties[property] || !this.hasOwnProperty(property)) {
303:         continue;
304:       }
305: 
306:       if (isEqual(this[property], defaults[property])) {
307:         continue;
308:       }
309: 
310:       model[property] = cloneDeep(this[property]);
311:     }
312: 
313:     // clean libraryPanel from collapsed rows
314:     if (this.type === 'row' && this.panels && this.panels.length > 0) {
315:       model.panels = this.panels.map((panel) => {
316:         if (panel.libraryPanel) {
317:           const { id, title, libraryPanel, gridPos } = panel;
318:           return {
319:             id,
320:             title,
321:             gridPos,
322:             libraryPanel: {
323:               uid: libraryPanel.uid,
324:               name: libraryPanel.name,
325:             },
326:           };
327:         }
328: 
329:         return panel;
330:       });
331:     }
332: 
333:     return model;
334:   }
335: 
336:   setIsViewing(isViewing: boolean) {
337:     this.isViewing = isViewing;
338:   }
339: 
340:   updateGridPos(newPos: GridPos, manuallyUpdated = true) {
341:     if (
342:       newPos.x === this.gridPos.x &&
343:       newPos.y === this.gridPos.y &&
344:       newPos.h === this.gridPos.h &&
345:       newPos.w === this.gridPos.w
346:     ) {
347:       return;
348:     }
349: 
350:     this.gridPos.x = newPos.x;
351:     this.gridPos.y = newPos.y;
352:     this.gridPos.w = newPos.w;
353:     this.gridPos.h = newPos.h;
354:     if (manuallyUpdated) {
355:       this.configRev++;
356:     }
357: 
358:     // Maybe a bit heavy. Could add a "GridPosChanged" event instead?
359:     this.render();
360:   }
361: 
362:   runAllPanelQueries({ dashboardUID, dashboardTimezone, timeData, width }: RunPanelQueryOptions) {
363:     if (this.type === 'row') {
364:       return;
365:     }
366:     this.getQueryRunner().run({
367:       datasource: this.datasource,
368:       queries: this.targets,
369:       panelId: this.id,
370:       dashboardUID: dashboardUID,
371:       timezone: dashboardTimezone,
372:       timeRange: timeData.timeRange,
373:       timeInfo: timeData.timeInfo,
374:       maxDataPoints: this.maxDataPoints || Math.floor(width),
375:       minInterval: this.interval,
376:       scopedVars: this.scopedVars,
377:       cacheTimeout: this.cacheTimeout,
378:       queryCachingTTL: this.queryCachingTTL,
379:       transformations: this.transformations,
380:       app: this.isEditing ? CoreApp.PanelEditor : this.isViewing ? CoreApp.PanelViewer : CoreApp.Dashboard,
381:     });
382:   }
383: 
384:   refresh() {
385:     this.hasRefreshed = true;
386:     this.events.publish(new RefreshEvent());
387:   }
388: 
389:   render() {
390:     if (!this.hasRefreshed) {
391:       this.refresh();
392:     } else {
393:       this.events.publish(new RenderEvent());
394:     }
395:   }
396: 
397:   public getOptionsToRemember(): any {
398:     return Object.keys(this).reduce((acc, property) => {
399:       if (notPersistedProperties[property] || mustKeepProps[property]) {
400:         return acc;
401:       }
402:       return {
403:         ...acc,
404:         [property]: (this as any)[property],
405:       };
406:     }, {});
407:   }
408: 
409:   private restorePanelOptions(pluginId: string) {
410:     const prevOptions = this.cachedPluginOptions[pluginId];
411: 
412:     if (!prevOptions) {
413:       return;
414:     }
415: 
416:     Object.keys(prevOptions.properties).map((property) => {
417:       (this as any)[property] = prevOptions.properties[property];
418:     });
419: 
420:     this.fieldConfig = restoreCustomOverrideRules(this.fieldConfig, prevOptions.fieldConfig);
421:   }
422: 
423:   applyPluginOptionDefaults(plugin: PanelPlugin, isAfterPluginChange: boolean) {
424:     const options = getPanelOptionsWithDefaults({
425:       plugin,
426:       currentOptions: this.options,
427:       currentFieldConfig: this.fieldConfig,
428:       isAfterPluginChange: isAfterPluginChange,
429:     });
430: 
431:     this.fieldConfig = options.fieldConfig;
