{"text":"URL: https://demo.sourcegraph.com/github.com/sg-evals/grafana--v10.2.0@6e54105447cef3c8b1025b1a3d5e76cd20213659/-/blob/packages/grafana-data/src/panel/getPanelOptionsWithDefaults.ts
1: import { mergeWith, isArray, isObject, unset, isEqual } from 'lodash';
2: 
3: import { FieldConfigOptionsRegistry } from '../field/FieldConfigOptionsRegistry';
4: import { fieldColorModeRegistry } from '../field/fieldColor';
5: import { FieldColorConfigSettings } from '../field/overrides/processors';
6: import { FieldColorModeId } from '../types/fieldColor';
7: import {
8:   ConfigOverrideRule,
9:   DynamicConfigValue,
10:   FieldConfigProperty,
11:   FieldConfigSource,
12: } from '../types/fieldOverrides';
13: import { ThresholdsConfig, ThresholdsMode } from '../types/thresholds';
14: 
15: import { PanelPlugin } from './PanelPlugin';
16: 
17: export interface Props {
18:   plugin: PanelPlugin;
19:   currentFieldConfig: FieldConfigSource;
20:   currentOptions: Record<string, any>;
21:   isAfterPluginChange: boolean;
22: }
23: 
24: export interface OptionDefaults {
25:   options: any;
26:   fieldConfig: FieldConfigSource;
27: }
28: 
29: /**
30:  * This will return the panel options with defaults applied.
31:  * Used internally, not intended for external use.
32:  * @internal
33:  */
34: export function getPanelOptionsWithDefaults({
35:   plugin,
36:   currentOptions,
37:   currentFieldConfig,
38:   isAfterPluginChange,
39: }: Props): OptionDefaults {
40:   const optionsWithDefaults = mergeWith({}, plugin.defaults, currentOptions || {}, (objValue, srcValue) => {
41:     if (isArray(srcValue)) {
42:       return srcValue;
43:     }
44:     return;
45:   });
46: 
47:   const fieldConfigWithDefaults = applyFieldConfigDefaults(currentFieldConfig, plugin);
48:   const fieldConfigWithOptimalColorMode = adaptFieldColorMode(plugin, fieldConfigWithDefaults, isAfterPluginChange);
49: 
50:   return { options: optionsWithDefaults, fieldConfig: fieldConfigWithOptimalColorMode };
51: }
52: 
53: function applyFieldConfigDefaults(existingFieldConfig: FieldConfigSource, plugin: PanelPlugin): FieldConfigSource {
54:   const pluginDefaults = plugin.fieldConfigDefaults;
55: 
56:   const result: FieldConfigSource = {
57:     defaults: mergeWith(
58:       {},
59:       pluginDefaults.defaults,
60:       existingFieldConfig ? existingFieldConfig.defaults : {},
61:       (objValue, srcValue) => {
62:         if (isArray(srcValue)) {
63:           return srcValue;
64:         }
65:         return;
66:       }
67:     ),
68:     overrides: existingFieldConfig?.overrides ?? [],
69:   };
70: 
71:   cleanProperties(result.defaults, '', plugin.fieldConfigRegistry);
72: 
73:   // Thresholds base values are null in JSON but need to be converted to -Infinity
74:   if (result.defaults.thresholds) {
75:     fixThresholds(result.defaults.thresholds);
76:   }
77: 
78:   // Filter out overrides for properties that cannot be found in registry
79:   result.overrides = filterFieldConfigOverrides(result.overrides, (prop) => {
80:     return plugin.fieldConfigRegistry.getIfExists(prop.id) !== undefined;
81:   });
82: 
83:   for (const override of result.overrides) {
84:     for (const property of override.properties) {
85:       if (property.id === 'thresholds') {
86:         fixThresholds(property.value);
87:       }
88:     }
89:   }
90: 
91:   return result;
92: }
93: 
94: /**
95:  * Used internally, not intended for external use.
96:  * @internal
97:  */
98: export function filterFieldConfigOverrides(
99:   overrides: ConfigOverrideRule[],
100:   condition: (value: DynamicConfigValue) => boolean
101: ): ConfigOverrideRule[] {
102:   return overrides
103:     .map((x) => {
104:       const properties = x.properties.filter(condition);
105: 
106:       return {
107:         ...x,
108:         properties,
109:       };
110:     })
111:     .filter((x) => x.properties.length > 0);
112: }
113: 
114: function cleanProperties(obj: any, parentPath: string, fieldConfigRegistry: FieldConfigOptionsRegistry) {
115:   let found = false;
116: 
117:   for (const propName of Object.keys(obj)) {
118:     const value = obj[propName];
119:     const fullPath = `${parentPath}${propName}`;
120:     const existsInRegistry = !!fieldConfigRegistry.getIfExists(fullPath);
121: 
122:     // need to check early here as some standard properties have nested properies
123:     if (existsInRegistry) {
124:       found = true;
125:       continue;
126:     }
127: 
128:     if (isArray(value) || !isObject(value)) {
129:       if (!existsInRegistry) {
130:         unset(obj, propName);
131:       }
132:     } else {
133:       const childPropFound = cleanProperties(value, `${fullPath}.`, fieldConfigRegistry);
134:       // If no child props found unset the main object
135:       if (!childPropFound) {
136:         unset(obj, propName);
137:       }
138:     }
139:   }
140: 
141:   return found;
142: }
143: 
144: function adaptFieldColorMode(
145:   plugin: PanelPlugin,
146:   fieldConfig: FieldConfigSource,
147:   isAfterPluginChange: boolean
148: ): FieldConfigSource {
149:   if (!isAfterPluginChange) {
150:     return fieldConfig;
151:   }
152: 
153:   // adjust to prefered field color setting if needed
154:   const color = plugin.fieldConfigRegistry.getIfExists(FieldConfigProperty.Color);
155: 
156:   if (color && color.settings) {
157:     const colorSettings: FieldColorConfigSettings = color.settings;
158:     const mode = fieldColorModeRegistry.getIfExists(fieldConfig.defaults.color?.mode);
159: 
160:     // When no support fo value colors, use classic palette
161:     if (!colorSettings.byValueSupport) {
162:       if (!mode || mode.isByValue) {
163:         fieldConfig.defaults.color = { mode: FieldColorModeId.PaletteClassic };
164:         return fieldConfig;
165:       }
166:     }
167: 
168:     // When supporting value colors and prefering thresholds, use Thresholds mode.
169:     // Otherwise keep current mode
170:     if (colorSettings.byValueSupport && colorSettings.preferThresholdsMode && mode?.id !== FieldColorModeId.Fixed) {
171:       if (!mode || !mode.isByValue) {
172:         fieldConfig.defaults.color = { mode: FieldColorModeId.Thresholds };
173:         return fieldConfig;
174:       }
175:     }
176: 
177:     // If panel support bySeries then we should default to that when switching to this panel as that is most likely
178:     // what users will expect. Example scenario a user who has a graph panel (time series) and switches to Gauge and
179:     // then back to time series we want the graph panel color mode to reset to classic palette and not preserve the
180:     // Gauge prefered thresholds mode.
181:     if (colorSettings.bySeriesSupport && mode?.isByValue) {
182:       fieldConfig.defaults.color = { mode: FieldColorModeId.PaletteClassic };
183:       return fieldConfig;
184:     }
185:   }
186:   return fieldConfig;
187: }
188: 
189: function fixThresholds(thresholds: ThresholdsConfig) {
190:   if (!thresholds.mode) {
191:     thresholds.mode = ThresholdsMode.Absolute;
192:   }
193: 
194:   if (!thresholds.steps) {
195:     thresholds.steps = [];
196:   } else if (thresholds.steps.length) {
197:     // First value is always -Infinity
198:     // JSON saves it as null
199:     thresholds.steps[0].value = -Infinity;
200:   }
201: }
202: 
203: /**
204:  * Used internally, not intended for external use.
205:  * @internal
206:  */
207: export function restoreCustomOverrideRules(current: FieldConfigSource, old: FieldConfigSource): FieldConfigSource {
208:   const result = {
209:     defaults: {
210:       ...current.defaults,
211:       custom: old.defaults.custom,
212:     },
213:     overrides: [...current.overrides],
214:   };
215: 
216:   for (const override of old.overrides) {
217:     for (const prop of override.properties) {
218:       if (isCustomFieldProp(prop)) {
219:         const currentOverride = result.overrides.find((o) => isEqual(o.matcher, override.matcher));
220:         if (currentOverride) {
221:           if (currentOverride !== override) {
222:             currentOverride.properties.push(prop);
223:           }
224:         } else {
225:           result.overrides.push(override);
226:         }
227:       }
228:     }
229:   }
230: 
231:   return result;
232: }
233: 
234: /**
235:  * Used internally, not intended for external use.
236:  * @internal
237:  */
238: export function isCustomFieldProp(prop: DynamicConfigValue): boolean {
239:   return prop.id.startsWith('custom.');
240: }
241: 
242: /**
243:  * Used internally, not intended for external use.
244:  * @internal
245:  */
246: export function isStandardFieldProp(prop: DynamicConfigValue): boolean {
247:   return !isCustomFieldProp(prop);
248: }
