78: export class DashboardExporter {
79:   async makeExportable(dashboard: DashboardModel) {
80:     // clean up repeated rows and panels,
81:     // this is done on the live real dashboard instance, not on a clone
82:     // so we need to undo this
83:     // this is pretty hacky and needs to be changed
84:     dashboard.cleanUpRepeats();
85: 
86:     const saveModel = dashboard.getSaveModelCloneOld();
87:     saveModel.id = null;
88: 
89:     // undo repeat cleanup
90:     dashboard.processRepeats();
91: 
92:     const inputs: Input[] = [];
93:     const requires: Requires = {};
94:     const datasources: DataSources = {};
95:     const variableLookup: { [key: string]: any } = {};
96:     const libraryPanels: Map<string, LibraryElementExport> = new Map<string, LibraryElementExport>();
97: 
98:     for (const variable of saveModel.getVariables()) {
99:       variableLookup[variable.name] = variable;
100:     }
101: 
102:     const templateizeDatasourceUsage = (obj: any, fallback?: DataSourceRef) => {
103:       if (obj.datasource === undefined) {
104:         obj.datasource = fallback;
105:         return;
106:       }
107: 
108:       let datasource = obj.datasource;
109:       let datasourceVariable: any = null;
110: 
111:       const datasourceUid: string = datasource?.uid;
112:       // ignore data source properties that contain a variable
113:       if (datasourceUid) {
114:         if (datasourceUid.indexOf('$') === 0) {
115:           datasourceVariable = variableLookup[datasourceUid.substring(1)];
116:           if (datasourceVariable && datasourceVariable.current) {
117:             datasource = datasourceVariable.current.value;
118:           }
119:         }
120:       }
121: 
122:       return getDataSourceSrv()
123:         .get(datasource)
124:         .then((ds) => {
125:           if (ds.meta?.builtIn) {
126:             return;
127:           }
128: 
129:           // add data source type to require list
130:           requires['datasource' + ds.meta?.id] = {
131:             type: 'datasource',
132:             id: ds.meta.id,
133:             name: ds.meta.name,
134:             version: ds.meta.info.version || '1.0.0',
135:           };
136: 
137:           // if used via variable we can skip templatizing usage
138:           if (datasourceVariable) {
139:             return;
140:           }
141: 
142:           const libraryPanel = obj.libraryPanel;
143:           const libraryPanelSuffix = !!libraryPanel ? '-for-library-panel' : '';
144:           let refName = 'DS_' + ds.name.replace(' ', '_').toUpperCase() + libraryPanelSuffix.toUpperCase();
145: 
146:           datasources[refName] = {
147:             name: refName,
148:             label: ds.name,
149:             description: '',
150:             type: 'datasource',
151:             pluginId: ds.meta?.id,
152:             pluginName: ds.meta?.name,
153:             usage: datasources[refName]?.usage,
154:           };
155: 
156:           if (!!libraryPanel) {
157:             const libPanels = datasources[refName]?.usage?.libraryPanels || [];
158:             libPanels.push({ name: libraryPanel.name, uid: libraryPanel.uid });
159: 
160:             datasources[refName].usage = {
161:               libraryPanels: libPanels,
162:             };
163:           }
164: 
165:           obj.datasource = { type: ds.meta.id, uid: '${' + refName + '}' };
166:         });
167:     };
168: 
169:     const processPanel = async (panel: PanelModel) => {
170:       if (panel.type !== 'row') {
171:         await templateizeDatasourceUsage(panel);
172: 
173:         if (panel.targets) {
174:           for (const target of panel.targets) {
175:             await templateizeDatasourceUsage(target, panel.datasource!);
176:           }
177:         }
178: 
179:         const panelDef: PanelPluginMeta = config.panels[panel.type];
180:         if (panelDef) {
