240:         type: 'grafana',
241:         id: 'grafana',
242:         name: 'Grafana',
243:         version: config.buildInfo.version,
244:       };
245: 
246:       // we need to process all panels again after all the promises are resolved
247:       // so all data sources, variables and targets have been templateized when we process library panels
248:       for (const panel of saveModel.panels) {
249:         await processLibraryPanels(panel);
250:         if (panel.collapsed !== undefined && panel.collapsed === true && panel.panels) {
251:           for (const rowPanel of panel.panels) {
252:             await processLibraryPanels(rowPanel);
253:           }
254:         }
255:       }
256: 
257:       each(datasources, (value: any) => {
258:         inputs.push(value);
259:       });
260: 
261:       // templatize constants
262:       for (const variable of saveModel.getVariables()) {
263:         if (isConstant(variable)) {
264:           const refName = 'VAR_' + variable.name.replace(' ', '_').toUpperCase();
265:           inputs.push({
266:             name: refName,
267:             type: 'constant',
268:             label: variable.label || variable.name,
269:             value: variable.query,
270:             description: '',
271:           });
272:           // update current and option
273:           variable.query = '${' + refName + '}';
274:           variable.current = {
275:             value: variable.query,
276:             text: variable.query,
277:             selected: false,
278:           };
279:           variable.options = [variable.current];
280:         }
281:       }
282: 
283:       const __elements = [...libraryPanels.entries()].reduce<Record<string, LibraryElementExport>>(
284:         (prev, [curKey, curLibPanel]) => {
285:           prev[curKey] = curLibPanel;
286:           return prev;
287:         },
288:         {}
289:       );
290: 
291:       // make inputs and requires a top thing
292:       const newObj: ExternalDashboard = defaults(
293:         {
294:           __inputs: inputs,
295:           __elements,
296:           __requires: sortBy(requires, ['id']),
297:         },
298:         saveModel
299:       );
300: 
301:       // Remove extraneous props from library panels
302:       for (let i = 0; i < newObj.panels.length; i++) {
303:         const libPanel = newObj.panels[i];
304:         if (isExportableLibraryPanel(libPanel)) {
305:           newObj.panels[i] = {
306:             gridPos: libPanel.gridPos,
307:             id: libPanel.id,
308:             libraryPanel: { uid: libPanel.libraryPanel.uid, name: libPanel.libraryPanel.name },
309:           };
310:         }
311:       }
312: 
313:       return newObj;
314:     } catch (err) {
315:       console.error('Export failed:', err);
316:       return {
317:         error: err,
318:       };
319:     }
320:   }
321: }
