99:     },
100:     setInputs: (state: Draft<ImportDashboardState>, action: PayloadAction<any[]>) => {
101:       state.inputs = {
102:         dataSources: action.payload.filter((p) => p.type === InputType.DataSource),
103:         constants: action.payload.filter((p) => p.type === InputType.Constant),
104:         libraryPanels: state.inputs.libraryPanels || [],
105:       };
106:     },
107:     setLibraryPanelInputs: (state: Draft<ImportDashboardState>, action: PayloadAction<LibraryPanelInput[]>) => {
108:       state.inputs.libraryPanels = action.payload;
109:     },
110:     fetchFailed: (state: Draft<ImportDashboardState>) => {
111:       state.dashboard = {};
112:       state.state = LoadingState.Error;
113:     },
114:     fetchDashboard: (state: Draft<ImportDashboardState>) => {
115:       state.state = LoadingState.Loading;
116:     },
117:   },
118: });
