1: import { createSlice, Draft, PayloadAction } from '@reduxjs/toolkit';
2: 
3: import { DataSourceInstanceSettings, LoadingState } from '@grafana/data';
4: 
5: import { LibraryElementDTO } from '../../library-panels/types';
6: 
7: export enum DashboardSource {
8:   Gcom = 0,
9:   Json = 1,
10: }
11: 
12: export interface ImportDashboardDTO {
13:   title: string;
14:   uid: string;
15:   gnetId: string;
16:   constants: string[];
17:   dataSources: DataSourceInstanceSettings[];
18:   elements: LibraryElementDTO[];
19:   folder: { uid: string; title?: string };
20: }
21: 
22: export enum InputType {
23:   DataSource = 'datasource',
24:   Constant = 'constant',
25:   LibraryPanel = 'libraryPanel',
26: }
27: 
28: export enum LibraryPanelInputState {
29:   New = 'new',
30:   Exists = 'exists',
31:   Different = 'different',
32: }
33: 
34: export interface DashboardInput {
35:   name: string;
36:   label: string;
37:   description?: string;
38:   info: string;
39:   value: string;
40:   type: InputType;
41: }
42: 
43: export interface DataSourceInput extends DashboardInput {
44:   pluginId: string;
45: }
46: 
47: export interface LibraryPanelInput {
48:   model: LibraryElementDTO;
49:   state: LibraryPanelInputState;
50: }
51: 
52: export interface DashboardInputs {
53:   dataSources: DataSourceInput[];
54:   constants: DashboardInput[];
55:   libraryPanels: LibraryPanelInput[];
56: }
57: 
58: export interface ImportDashboardState {
59:   meta: { updatedAt: string; orgName: string };
60:   dashboard: any;
61:   source: DashboardSource;
62:   inputs: DashboardInputs;
63:   state: LoadingState;
64: }
65: 
66: export const initialImportDashboardState: ImportDashboardState = {
67:   meta: { updatedAt: '', orgName: '' },
68:   dashboard: {},
69:   source: DashboardSource.Json,
70:   inputs: {} as DashboardInputs,
71:   state: LoadingState.NotStarted,
72: };
73: 
74: const importDashboardSlice = createSlice({
75:   name: 'manageDashboards',
76:   initialState: initialImportDashboardState,
77:   reducers: {
78:     setGcomDashboard: (state: Draft<ImportDashboardState>, action: PayloadAction<any>) => {
79:       state.dashboard = {
80:         ...action.payload.json,
81:         id: null,
82:       };
83:       state.meta = { updatedAt: action.payload.updatedAt, orgName: action.payload.orgName };
84:       state.source = DashboardSource.Gcom;
85:       state.state = LoadingState.Done;
86:     },
87:     setJsonDashboard: (state: Draft<ImportDashboardState>, action: PayloadAction<any>) => {
88:       state.dashboard = {
89:         ...action.payload,
90:         id: null,
91:       };
92:       state.meta = initialImportDashboardState.meta;
93:       state.source = DashboardSource.Json;
94:       state.state = LoadingState.Done;
95:     },
96:     clearDashboard: (state: Draft<ImportDashboardState>) => {
97:       state.dashboard = {};
98:       state.state = LoadingState.NotStarted;
99:     },
100:     setInputs: (state: Draft<ImportDashboardState>, action: PayloadAction<any[]>) => {
101:       state.inputs = {
102:         dataSources: action.payload.filter((p) => p.type === InputType.DataSource),
103:         constants: action.payload.filter((p) => p.type === InputType.Constant),
104:         libraryPanels: state.inputs.libraryPanels || [],
105:       };
106:     },
107:     setLibraryPanelInputs: (state: Draft<ImportDashboardState>, action: PayloadAction<LibraryPanelInput[]>) => {
108:       state.inputs.libraryPanels = action.payload;
109:     },
110:     fetchFailed: (state: Draft<ImportDashboardState>) => {
111:       state.dashboard = {};
112:       state.state = LoadingState.Error;
113:     },
114:     fetchDashboard: (state: Draft<ImportDashboardState>) => {
115:       state.state = LoadingState.Loading;
116:     },
117:   },
118: });
119: 
120: export const {
121:   clearDashboard,
122:   setInputs,
123:   setGcomDashboard,
124:   setJsonDashboard,
125:   setLibraryPanelInputs,
126:   fetchFailed,
127:   fetchDashboard,
128: } = importDashboardSlice.actions;
129: 
130: export const importDashboardReducer = importDashboardSlice.reducer;
131: 
132: export default {
133:   importDashboard: importDashboardReducer,
134: };
