425:  * @returns TableCellOptions object in the correct format
426:  * relative to the old display mode.
427:  */
428: export function migrateTableDisplayModeToCellOptions(displayMode: TableCellDisplayMode): TableCellOptions {
429:   switch (displayMode) {
430:     // In the case of the gauge we move to a different option
431:     case 'basic':
432:     case 'gradient-gauge':
433:     case 'lcd-gauge':
434:       let gaugeMode = BarGaugeDisplayMode.Basic;
435: 
436:       if (displayMode === 'gradient-gauge') {
437:         gaugeMode = BarGaugeDisplayMode.Gradient;
438:       } else if (displayMode === 'lcd-gauge') {
439:         gaugeMode = BarGaugeDisplayMode.Lcd;
440:       }
441: 
442:       return {
443:         type: TableCellDisplayMode.Gauge,
444:         mode: gaugeMode,
445:       };
446:     // Also true in the case of the color background
447:     case 'color-background':
448:     case 'color-background-solid':
449:       let mode = TableCellBackgroundDisplayMode.Basic;
450: 
451:       // Set the new mode field, somewhat confusingly the
452:       // color-background mode is for gradient display
453:       if (displayMode === 'color-background') {
454:         mode = TableCellBackgroundDisplayMode.Gradient;
455:       }
456: 
457:       return {
458:         type: TableCellDisplayMode.ColorBackground,
459:         mode: mode,
460:       };
461:     default:
462:       return {
463:         // @ts-ignore
464:         type: displayMode,
465:       };
466:   }
467: }
