142: func NewDashboardFromJson(data *simplejson.Json) *Dashboard {
143: 	dash := &Dashboard{}
144: 	dash.Data = data
145: 	dash.Title = dash.Data.Get("title").MustString()
146: 	dash.UpdateSlug()
147: 	update := false
148: 
149: 	if id, err := dash.Data.Get("id").Float64(); err == nil {
150: 		dash.ID = int64(id)
151: 		update = true
152: 	}
153: 
154: 	if uid, err := dash.Data.Get("uid").String(); err == nil {
155: 		dash.UID = uid
156: 		update = true
157: 	}
158: 
159: 	if version, err := dash.Data.Get("version").Float64(); err == nil && update {
160: 		dash.Version = int(version)
161: 		dash.Updated = time.Now()
162: 	} else {
163: 		dash.Data.Set("version", 0)
164: 		dash.Created = time.Now()
165: 		dash.Updated = time.Now()
166: 	}
167: 
168: 	if gnetId, err := dash.Data.Get("gnetId").Float64(); err == nil {
169: 		dash.GnetID = int64(gnetId)
170: 	}
171: 
172: 	return dash
173: }
174: 
175: // GetDashboardModel turns the command into the saveable model
176: func (cmd *SaveDashboardCommand) GetDashboardModel() *Dashboard {
177: 	dash := NewDashboardFromJson(cmd.Dashboard)
178: 	userID := cmd.UserID
179: 
180: 	if userID == 0 {
181: 		userID = -1
182: 	}
183: 
184: 	dash.UpdatedBy = userID
185: 	dash.OrgID = cmd.OrgID
186: 	dash.PluginID = cmd.PluginID
187: 	dash.IsFolder = cmd.IsFolder
188: 	dash.FolderID = cmd.FolderID
189: 	dash.UpdateSlug()
190: 	return dash
191: }
192: 
193: // UpdateSlug updates the slug
194: func (d *Dashboard) UpdateSlug() {
195: 	title := d.Data.Get("title").MustString()
196: 	d.Slug = slugify.Slugify(title)
197: }
