1: import { omitBy, isNil, isNumber, defaultTo, groupBy } from 'lodash';
2: 
3: import {
4:   PanelModel,
5:   FieldMatcherID,
6:   ConfigOverrideRule,
7:   ThresholdsMode,
8:   ThresholdsConfig,
9:   FieldConfig,
10:   DataFrame,
11:   FieldType,
12: } from '@grafana/data';
13: import { ReduceTransformerOptions } from '@grafana/data/src/transformations/transformers/reduce';
14: 
15: import { Options } from './panelcfg.gen';
16: 
17: /**
18:  * At 7.0, the `table` panel was swapped from an angular implementation to a react one.
19:  * The models do not match, so this process will delegate to the old implementation when
20:  * a saved table configuration exists.
21:  */
22: export const tableMigrationHandler = (panel: PanelModel<Options>): Partial<Options> => {
23:   // Table was saved as an angular table, lets just swap to the 'table-old' panel
24:   if (!panel.pluginVersion && 'columns' in panel) {
25:     console.log('Was angular table', panel);
26:   }
27: 
28:   // Nothing changed
29:   return panel.options;
30: };
31: 
32: const transformsMap = {
33:   timeseries_to_rows: 'seriesToRows',
34:   timeseries_to_columns: 'seriesToColumns',
35:   timeseries_aggregations: 'reduce',
36:   table: 'merge',
37: };
38: 
39: const columnsMap = {
40:   avg: 'mean',
41:   min: 'min',
42:   max: 'max',
43:   total: 'sum',
44:   current: 'lastNotNull',
45:   count: 'count',
46: };
47: 
48: const colorModeMap = {
49:   cell: 'color-background',
50:   row: 'color-background',
51:   value: 'color-text',
52: };
53: 
54: type Transformations = keyof typeof transformsMap;
55: 
56: type Transformation = {
57:   id: string;
58:   options: ReduceTransformerOptions;
59: };
60: 
61: type Columns = keyof typeof columnsMap;
62: 
63: type Column = {
64:   value: Columns;
65:   text: string;
66: };
67: 
68: type ColorModes = keyof typeof colorModeMap;
69: 
70: const generateThresholds = (thresholds: string[], colors: string[]) => {
71:   return [-Infinity, ...thresholds].map((threshold, idx) => ({
72:     color: colors[idx],
73:     value: isNumber(threshold) ? threshold : parseInt(threshold, 10),
74:   }));
75: };
76: 
77: const migrateTransformations = (
78:   panel: PanelModel<Partial<Options>> | any,
79:   oldOpts: { columns: any; transform: Transformations }
80: ) => {
81:   const transformations: Transformation[] = panel.transformations ?? [];
82:   if (Object.keys(transformsMap).includes(oldOpts.transform)) {
83:     const opts: ReduceTransformerOptions = {
84:       reducers: [],
85:     };
86:     if (oldOpts.transform === 'timeseries_aggregations') {
87:       opts.includeTimeField = false;
88:       opts.reducers = oldOpts.columns.map((column: Column) => columnsMap[column.value]);
89:     }
90:     transformations.push({
91:       id: transformsMap[oldOpts.transform],
92:       options: opts,
93:     });
94:   }
95:   return transformations;
96: };
97: 
98: type Style = {
99:   unit: string;
100:   type: string;
101:   alias: string;
102:   decimals: number;
103:   colors: string[];
104:   colorMode: ColorModes;
105:   pattern: string;
106:   thresholds: string[];
107:   align?: string;
108:   dateFormat: string;
109:   link: boolean;
110:   linkTargetBlank?: boolean;
111:   linkTooltip?: string;
112:   linkUrl?: string;
113: };
114: 
115: const migrateTableStyleToOverride = (style: Style) => {
116:   const fieldMatcherId = /^\/.*\/$/.test(style.pattern) ? FieldMatcherID.byRegexp : FieldMatcherID.byName;
117:   const override: ConfigOverrideRule = {
118:     matcher: {
119:       id: fieldMatcherId,
120:       options: style.pattern,
121:     },
122:     properties: [],
123:   };
124: 
125:   if (style.alias) {
126:     override.properties.push({
127:       id: 'displayName',
128:       value: style.alias,
129:     });
130:   }
131: 
132:   if (style.unit) {
133:     override.properties.push({
134:       id: 'unit',
135:       value: style.unit,
136:     });
137:   }
138: 
139:   if (style.decimals) {
140:     override.properties.push({
141:       id: 'decimals',
142:       value: style.decimals,
143:     });
144:   }
145: 
146:   if (style.type === 'date') {
147:     override.properties.push({
148:       id: 'unit',
149:       value: `time: ${style.dateFormat}`,
150:     });
151:   }
152: 
153:   if (style.link) {
154:     override.properties.push({
155:       id: 'links',
156:       value: [
157:         {
158:           title: defaultTo(style.linkTooltip, ''),
159:           url: defaultTo(style.linkUrl, ''),
160:           targetBlank: defaultTo(style.linkTargetBlank, false),
161:         },
162:       ],
163:     });
164:   }
165: 
166:   if (style.colorMode) {
167:     override.properties.push({
168:       id: 'custom.cellOptions',
169:       value: {
170:         type: colorModeMap[style.colorMode],
171:       },
172:     });
173:   }
174: 
175:   if (style.align) {
176:     override.properties.push({
177:       id: 'custom.align',
178:       value: style.align === 'auto' ? null : style.align,
179:     });
180:   }
181: 
182:   if (style.thresholds?.length) {
183:     override.properties.push({
184:       id: 'thresholds',
185:       value: {
186:         mode: ThresholdsMode.Absolute,
187:         steps: generateThresholds(style.thresholds, style.colors),
188:       },
189:     });
190:   }
191: 
192:   return override;
193: };
194: 
195: const migrateDefaults = (prevDefaults: Style) => {
196:   let defaults: FieldConfig = {
197:     custom: {},
198:   };
199:   if (prevDefaults) {
200:     defaults = omitBy(
201:       {
202:         unit: prevDefaults.unit,
203:         decimals: prevDefaults.decimals,
204:         displayName: prevDefaults.alias,
205:         custom: {
206:           align: prevDefaults.align === 'auto' ? null : prevDefaults.align,
207:         },
208:       },
209:       isNil
210:     );
211: 
212:     if (prevDefaults.thresholds.length) {
213:       const thresholds: ThresholdsConfig = {
214:         mode: ThresholdsMode.Absolute,
215:         steps: generateThresholds(prevDefaults.thresholds, prevDefaults.colors),
216:       };
217:       defaults.thresholds = thresholds;
218:     }
219: 
220:     if (prevDefaults.colorMode) {
221:       defaults.custom.cellOptions = {
222:         type: colorModeMap[prevDefaults.colorMode],
223:       };
224:     }
225:   }
226:   return defaults;
227: };
228: 
229: /**
230:  * This is called when the panel changes from another panel
231:  */
232: export const tablePanelChangedHandler = (
233:   panel: PanelModel<Partial<Options>> | any,
234:   prevPluginId: string,
235:   prevOptions: any
236: ) => {
237:   // Changing from angular table panel
238:   if (prevPluginId === 'table-old' && prevOptions.angular) {
239:     const oldOpts = prevOptions.angular;
240:     const transformations = migrateTransformations(panel, oldOpts);
241:     const prevDefaults = oldOpts.styles.find((style: any) => style.pattern === '/.*/');
242:     const defaults = migrateDefaults(prevDefaults);
243:     const overrides = oldOpts.styles.filter((style: any) => style.pattern !== '/.*/').map(migrateTableStyleToOverride);
244: 
245:     panel.transformations = transformations;
246:     panel.fieldConfig = {
247:       defaults,
248:       overrides,
249:     };
250:   }
251: 
252:   return {};
253: };
254: 
255: const getMainFrames = (frames: DataFrame[] | null) => {
256:   return frames?.filter((df) => df.meta?.custom?.parentRowIndex === undefined) || [frames?.[0]];
257: };
258: 
259: /**
260:  * In 9.3 meta.custom.parentRowIndex was introduced to support sub-tables.
261:  * In 10.2 meta.custom.parentRowIndex was deprecated in favor of FieldType.nestedFrames, which supports multiple nested frames.
262:  * Migrate DataFrame[] from using meta.custom.parentRowIndex to using FieldType.nestedFrames
263:  */
264: export const migrateFromParentRowIndexToNestedFrames = (frames: DataFrame[] | null) => {
265:   const migratedFrames: DataFrame[] = [];
266:   const mainFrames = getMainFrames(frames).filter(
267:     (frame: DataFrame | undefined): frame is DataFrame => !!frame && frame.length !== 0
268:   );
269: 
270:   mainFrames?.forEach((frame) => {
271:     const subFrames = frames?.filter((df) => frame.refId === df.refId && df.meta?.custom?.parentRowIndex !== undefined);
272:     const subFramesGrouped = groupBy(subFrames, (frame: DataFrame) => frame.meta?.custom?.parentRowIndex);
273:     const subFramesByIndex = Object.keys(subFramesGrouped).map((key) => subFramesGrouped[key]);
274:     const migratedFrame = { ...frame };
275: 
276:     if (subFrames && subFrames.length > 0) {
277:       migratedFrame.fields.push({
278:         name: 'nested',
279:         type: FieldType.nestedFrames,
280:         config: {},
281:         values: subFramesByIndex,
282:       });
283:     }
284:     migratedFrames.push(migratedFrame);
285:   });
286: 
287:   return migratedFrames;
288: };
289: 
290: export const hasDeprecatedParentRowIndex = (frames: DataFrame[] | null) => {
291:   return frames?.some((df) => df.meta?.custom?.parentRowIndex !== undefined);
292: };
